import{_ as n,c as a,o as e,a2 as s}from"./chunks/framework.BEriqdm5.js";const h=JSON.parse('{"title":"AGENTS.md — NexusNote 组件文档维护指南","description":"","frontmatter":{},"headers":[],"relativePath":"AGENTS.md","filePath":"AGENTS.md","lastUpdated":1792664902000}'),d={name:"AGENTS.md"};function o(p,t,c,i,l,r){return e(),a("div",null,t[0]||(t[0]=[s('<h1 id="agents-md-—-nexusnote-组件文档维护指南" tabindex="-1">AGENTS.md — NexusNote 组件文档维护指南 <a class="header-anchor" href="#agents-md-—-nexusnote-组件文档维护指南" aria-label="Permalink to &quot;AGENTS.md — NexusNote 组件文档维护指南&quot;">​</a></h1><p>本文件用于指导在 VitePress 站点中编写/维护 <strong>UI 组件文档</strong>（<code>src/tg/ui/</code>）。写组件文档前先读本文件，按其中的数据源、组件清单与写作规范执行。</p><hr><h2 id="_1-数据源-权威-以实际源码为准" tabindex="-1">1. 数据源（权威，以实际源码为准） <a class="header-anchor" href="#_1-数据源-权威-以实际源码为准" aria-label="Permalink to &quot;1. 数据源（权威，以实际源码为准）&quot;">​</a></h2><p>组件文档展示的内容来自 monorepo 组件库 <strong>ui-taibai-vue</strong>：</p><table tabindex="0"><thead><tr><th>用途</th><th>路径</th></tr></thead><tbody><tr><td>通用组件源码</td><td><code>/Users/zthz/Downloads/LTB/code/nexus-monorepo/packages/ui-taibai-vue/src/components/</code></td></tr><tr><td>功能组件源码</td><td><code>/Users/zthz/Downloads/LTB/code/nexus-monorepo/packages/ui-taibai-vue/src/componentsui/</code></td></tr><tr><td>组件注册表</td><td><code>/Users/zthz/Downloads/LTB/code/nexus-monorepo/packages/ui-taibai-vue/src/components/components.ts</code></td></tr><tr><td>包导出入口</td><td><code>/Users/zthz/Downloads/LTB/code/nexus-monorepo/packages/ui-taibai-vue/src/index.ts</code></td></tr></tbody></table><p><strong>写文档时</strong>：打开对应组件的 <code>index.vue</code> / <code>index.ts</code>，从 <code>defineProps</code> / <code>defineEmits</code> / 插槽 / 注释中提取真实 API，不要凭记忆编造。</p><h2 id="_2-文档位置与入口" tabindex="-1">2. 文档位置与入口 <a class="header-anchor" href="#_2-文档位置与入口" aria-label="Permalink to &quot;2. 文档位置与入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>页面</th><th>文件</th><th>内容</th></tr></thead><tbody><tr><td>通用组件（总览）</td><td><code>src/tg/ui/components.md</code></td><td>全部自研组件（零依赖）总览 + 组件索引</td></tr><tr><td>通用组件（单组件页）</td><td><code>src/tg/ui/components/&lt;name&gt;.md</code></td><td>每个组件独立页面：button/badge/card/divider/tag/tooltip/input/select/switch/dialog/tabs/space/breadcrumb/pagination/validcode/message</td></tr><tr><td>功能组件</td><td><code>src/tg/ui/components-function.md</code></td><td>业务场景组件（componentsui）</td></tr></tbody></table><ul><li>侧边栏注册：<code>.vitepress/config.mts</code> 中 <code>uiList</code> 的 <strong>&quot;UI组件库&quot;</strong> 分组——&quot;通用组件&quot;为可展开分组（带 link 到总览页，items 为 16 个组件页，顺序与 <code>apps/WebVue/src/views/gongfu/componentsview/taibaiui/index.vue</code> 左侧列表一致），&quot;功能组件&quot;为单页链接。</li><li>文档与示例使用<strong>实际注册名</strong>（即组件文件名，无前缀，如 <code>Button</code>、<code>Badge</code>、<code>Input</code>），与 <code>apps/WebVue/src/views/gongfu/componentsview/taibaiui/index.vue</code> 中的用法一致；<code>Message</code> 为函数式调用不注册为组件。</li></ul><h2 id="_3-组件清单" tabindex="-1">3. 组件清单 <a class="header-anchor" href="#_3-组件清单" aria-label="Permalink to &quot;3. 组件清单&quot;">​</a></h2><h3 id="通用组件-16-个-components-md" tabindex="-1">通用组件（16 个，components.md） <a class="header-anchor" href="#通用组件-16-个-components-md" aria-label="Permalink to &quot;通用组件（16 个，components.md）&quot;">​</a></h3><p><strong>基础组件（9）</strong></p><table tabindex="0"><thead><tr><th>注册名</th><th>源码</th><th>说明</th></tr></thead><tbody><tr><td>Button</td><td><code>components/Button</code></td><td>按钮，variant：default/secondary/destructive/outline/ghost/link</td></tr><tr><td>Input</td><td><code>components/Input</code></td><td>输入框（原生 input，type/disabled/clearable）</td></tr><tr><td>Select</td><td><code>components/Select</code></td><td>选择器，options: <code>{label, value, disabled?}[]</code>，disabled</td></tr><tr><td>Switch</td><td><code>components/Switch</code></td><td>开关，activeText/inactiveText/disabled</td></tr><tr><td>Badge</td><td><code>components/Badge</code></td><td>徽标，count/max/dot/showZero/color</td></tr><tr><td>Tag</td><td><code>components/Tag</code></td><td>标签，variant 6 色 + size + closable</td></tr><tr><td>Card</td><td><code>components/Card</code></td><td>卡片，title/shadow + header/footer 插槽</td></tr><tr><td>Divider</td><td><code>components/Divider</code></td><td>分割线，direction/contentPosition</td></tr><tr><td>Space</td><td><code>components/Space</code></td><td>间距，size/wrap</td></tr></tbody></table><p><strong>反馈组件（6）</strong></p><table tabindex="0"><thead><tr><th>注册名</th><th>源码</th><th>说明</th></tr></thead><tbody><tr><td>Dialog</td><td><code>components/Dialog</code></td><td>对话框，v-model + title/width + footer 插槽（teleport 到 body）</td></tr><tr><td>Tabs</td><td><code>components/Tabs</code></td><td>标签页，tabs: <code>{name, label, disabled?}[]</code>，具名插槽按 name</td></tr><tr><td>Tooltip</td><td><code>components/Tooltip</code></td><td>气泡提示，content/placement + content 插槽</td></tr><tr><td>Breadcrumb</td><td><code>components/Breadcrumb</code></td><td>面包屑，items + separator + navigate 事件</td></tr><tr><td>Pagination</td><td><code>components/Pagination</code></td><td>分页，聚合事件 <code>pagination({currentPage, pageSize})</code></td></tr><tr><td>Message</td><td><code>components/Message</code></td><td>消息提示（函数式）：message/success/error/warning/info</td></tr></tbody></table><p><strong>自研组件（1）</strong></p><table tabindex="0"><thead><tr><th>注册名</th><th>源码</th><th>说明</th></tr></thead><tbody><tr><td>ValidCode</td><td><code>components/ValidCode</code></td><td>图形验证码，length/width/height，点击刷新</td></tr></tbody></table><h3 id="功能组件-3-个-components-function-md" tabindex="-1">功能组件（3 个，components-function.md） <a class="header-anchor" href="#功能组件-3-个-components-function-md" aria-label="Permalink to &quot;功能组件（3 个，components-function.md）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>文档名</th><th>源码</th><th>说明</th></tr></thead><tbody><tr><td>TimeLineTurn</td><td><code>componentsui/TimeLineTurn</code></td><td>拐弯时间线，SVG 轨迹节点图（time+label）</td></tr><tr><td>CsdnErweimaCard</td><td><code>componentsui/CsdnErweimaCard</code></td><td>二维码营销卡片，固定设计稿 900×560 自适应缩放</td></tr><tr><td>ZanwuShuju</td><td><code>componentsui/ZanwuShuju</code></td><td>暂无数据空状态占位</td></tr></tbody></table><h2 id="_4-写作规范-每个组件固定结构" tabindex="-1">4. 写作规范（每个组件固定结构） <a class="header-anchor" href="#_4-写作规范-每个组件固定结构" aria-label="Permalink to &quot;4. 写作规范（每个组件固定结构）&quot;">​</a></h2><p>在 md 中按以下顺序书写，保持全站一致：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>### 组件名 中文名（一句话说明）</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**Props**</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>| 属性 | 类型 | 默认值 | 说明 |        ← 从源码 defineProps/withDefaults 提取</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**事件**（无事件可省略）</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>| 事件 | 参数 | 说明 |          ← 从 defineEmits 提取</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**Slots**（无插槽可省略）</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>| 插槽 | 说明 |                  ← 默认插槽/具名插槽</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>**示例**</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>```vue</span></span>\n<span class="line"><span>&lt;template&gt;...&lt;/template&gt;          ← 可直接复制的用法</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span></span></span>\n<span class="line"><span>- 类型/默认值必须与源码一致（如 `variant?: &#39;default&#39; | &#39;secondary&#39; | ...`）。</span></span>\n<span class="line"><span>- 全部组件为自研零依赖；仅当源码确实透传 attrs 时才注明&quot;其余属性透传&quot;，自研原生实现不写该句。</span></span>\n<span class="line"><span>- 示例代码写最小可用用例，贴近真实业务。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## 5. 维护流程</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>新增或修改组件文档时：</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>1. 读源码：`defineProps` / `withDefaults` / `defineEmits` / 插槽 / 注释。</span></span>\n<span class="line"><span>2. 判断分类：`components/` 下 → 通用组件（总览 components.md + 单组件页 `components/&lt;name&gt;.md`）；`componentsui/` 下 → 功能组件（components-function.md）。</span></span>\n<span class="line"><span>3. 按第 4 节规范更新对应 md：新增组件时创建 `components/&lt;name&gt;.md`（frontmatter title + `# 展示名`），并在总览表、侧边栏 items 中登记。</span></span>\n<span class="line"><span>4. 若新增页面文件，在 `config.mts` 的 `uiList` → &quot;UI组件库&quot; → &quot;通用组件&quot; items 中注册（text + link），顺序参考 taibaiui 左侧列表。</span></span>\n<span class="line"><span>5. 验证：dev server（端口 8089）访问 `http://localhost:8089/src/tg/ui/components/&lt;name&gt;.html` 返回 200。</span></span>\n<span class="line"><span>6. 部署时在项目根目录运行 `./deploy.sh`（构建 + 同步到 github 仓库 + 推送）。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## 7. 部署注意事项</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>- GitHub Pages 自定义域名（`www.taibai.cyou`）依赖仓库根目录的 `CNAME` 文件，**不要删除** `public/CNAME`（构建时自动复制进 `dist/`）；`deploy.sh` 已用 `--filter=&#39;P CNAME&#39;` 防止 rsync `--delete` 误删。若域名失效，先检查 GitHub Pages 设置里自定义域名是否还在、仓库根目录 CNAME 是否存在。</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>## 6. 其他注意事项</span></span>\n<span class="line"><span></span></span>\n<span class="line"><span>- 文档只描述**已实际实现**的组件 API；源码中标注 🔨/TODO 的不要写成已支持。</span></span>\n<span class="line"><span>- 组件注册名 = 组件文件名（无前缀），文档/示例直接用注册名（如 `Button`、`Breadcrumb`），与 taibaiui 展示页用法一致。</span></span>\n<span class="line"><span>- 图片等静态资源如引用外部 URL（如 `diag.wuzhengai.com`），文档中注明&quot;内网不可访问时可替换为本地资源&quot;。</span></span></code></pre></div>',24)]))}const m=n(d,[["render",o]]);export{h as __pageData,m as default};
